/// <reference path="./audioWorklet.d.ts" />
import type { EngineModule } from "./engineModule.d.ts";
// @ts-expect-error -- build artifact, see engineModule.d.ts and native/build.sh
import createEngineModule from "./generated/engine.js";
import type { HostCommand, WorkletEvent } from "../runtime/commandProtocol";
import { InstrumentKind } from "../runtime/types";
import type { EffectKindInfo, InstrumentKindInfo, ModulationCapabilities } from "../runtime/types";

// This is the entire realtime boundary: everything below runs on the browser's dedicated
// audio rendering thread, never on the main/React thread. It has no notion of pads,
// patterns, or React — only samples, voices, and the WASM engine's flat ABI. See
// ARCHITECTURE.md, "Where WASM is used" and "Threading model".
//
// Diagnostics are posted periodically (not every block) precisely so the main thread never
// becomes a dependency of the render loop: process() never waits on anything.
const DIAGNOSTICS_INTERVAL_BLOCKS = 20;
// Meters are read-and-cleared by the engine, so the rate only sets how often the UI is told,
// not how accurate the peaks are. 8 blocks of 128 frames is ~47 Hz at 48 kHz.
const METERS_INTERVAL_BLOCKS = 8;

class EngineProcessor extends AudioWorkletProcessor {
  private module: EngineModule | null = null;
  private blockCounter = 0;
  private metersWereActive = false;
  // captureId -> the SampleId the caller wants the eventual capture-complete event to carry,
  // recorded at arm time (armCapture() has no synchronous reply, so this is how the id
  // survives until the engine autonomously finishes the capture — see processUnsafe()).
  private armedCaptureResultIds = new Map<number, number>();

  constructor(options?: AudioWorkletNodeOptions) {
    super();
    const maxVoices = (options?.processorOptions?.maxVoices as number | undefined) ?? 128;
    const outputChannels = (options?.processorOptions?.outputChannels as number | undefined) ?? 2;

    this.port.onmessage = (event: MessageEvent<HostCommand>) => this.handleCommand(event.data);

    createEngineModule().then((mod: EngineModule) => {
      this.module = mod;
      mod._webdsp_init(sampleRate, outputChannels, maxVoices);
      this.postEvent({
        type: "ready",
        sampleRate,
        outputChannels: mod._webdsp_output_channels(),
        maxVoices: mod._webdsp_max_voices(),
        renderQuantumFrames: 128,
        maxCaptureSeconds: mod._webdsp_max_capture_seconds(),
        instruments: this.readInstrumentMetadata(mod),
        effects: this.readEffectMetadata(mod),
        modulation: this.readModulationMetadata(mod),
      });
    });
  }

  // Parameter tables come from the engine itself so JS never duplicates ranges/defaults.
  //
  // cstr() deliberately doesn't use TextDecoder: AudioWorkletGlobalScope doesn't expose it
  // (unlike a regular Worker/Window global scope — it's one of several Web APIs the worklet
  // scope omits), so `new TextDecoder()` throws a ReferenceError the moment this runs, which
  // happens inside the constructor's module-ready callback — i.e. on every single
  // AudioRuntime.create(), not just when an instrument is actually used. That throw pre-empts
  // the "ready" postEvent() below entirely, so the worklet module never finishes initializing
  // and no audio of any kind (sample playback included) works. Every param name/unit this
  // reads is a short ASCII identifier from a C++ constexpr table (see docs/instruments.md),
  // never user data, so a plain byte-for-char decode is exact, not just "good enough".
  private readInstrumentMetadata(m: EngineModule): InstrumentKindInfo[] {
    const cstr = (ptr: number): string => {
      let end = ptr;
      while (m.HEAPU8[end] !== 0) end++;
      let result = "";
      for (let i = ptr; i < end; i++) result += String.fromCharCode(m.HEAPU8[i]);
      return result;
    };
    const kinds: InstrumentKindInfo[] = [];
    for (const kind of [
      InstrumentKind.Kick,
      InstrumentKind.Snare,
      InstrumentKind.Clap,
      InstrumentKind.Tom,
      InstrumentKind.HiHat,
      InstrumentKind.Bass,
      InstrumentKind.Pulse,
      InstrumentKind.Pad,
      InstrumentKind.Fm,
      InstrumentKind.Hypersaw,
      InstrumentKind.PwmBeast,
      InstrumentKind.DmThump,
      InstrumentKind.DmMetal,
      InstrumentKind.DmTone,
      InstrumentKind.DmCrack,
      InstrumentKind.DmChaos,
      InstrumentKind.PercSynth,
      InstrumentKind.Edge,
    ]) {
      const params = [];
      const n = m._webdsp_instrument_param_count(kind);
      for (let i = 0; i < n; i++) {
        params.push({
          id: m._webdsp_instrument_param_id(kind, i),
          name: cstr(m._webdsp_instrument_param_name(kind, i)),
          min: m._webdsp_instrument_param_min(kind, i),
          max: m._webdsp_instrument_param_max(kind, i),
          default: m._webdsp_instrument_param_default(kind, i),
          unit: cstr(m._webdsp_instrument_param_unit(kind, i)),
          modulation: (["none", "linear", "log"] as const)[m._webdsp_instrument_param_mod(kind, i)] ?? "none",
        });
      }
      kinds.push({
        kind,
        id: cstr(m._webdsp_instrument_kind_id(kind)),
        name: cstr(m._webdsp_instrument_kind_name(kind)),
        category: cstr(m._webdsp_instrument_kind_category(kind)),
        params,
      });
    }
    return kinds;
  }

  private readEffectMetadata(m: EngineModule): EffectKindInfo[] {
    const cstr = (ptr: number): string => {
      let s = "";
      for (let i = ptr; m.HEAPU8[i] !== 0; i++) s += String.fromCharCode(m.HEAPU8[i]);
      return s;
    };
    const kinds: EffectKindInfo[] = [];
    for (let kind = 0; m._webdsp_fx_param_count(kind) > 0; kind++) {
      const params = [];
      for (let i = 0; i < m._webdsp_fx_param_count(kind); i++) {
        params.push({
          id: m._webdsp_fx_param_id(kind, i),
          name: cstr(m._webdsp_fx_param_name(kind, i)),
          min: m._webdsp_fx_param_min(kind, i),
          max: m._webdsp_fx_param_max(kind, i),
          default: m._webdsp_fx_param_default(kind, i),
          unit: cstr(m._webdsp_fx_param_unit(kind, i)),
          modulation: (["none", "linear", "log"] as const)[m._webdsp_fx_param_mod(kind, i)] ?? "none",
        });
      }
      kinds.push({ kind, params });
    }
    return kinds;
  }

  private readModulationMetadata(m: EngineModule): ModulationCapabilities {
    const cstr = (ptr: number): string => {
      let s = "";
      for (let i = ptr; m.HEAPU8[i] !== 0; i++) s += String.fromCharCode(m.HEAPU8[i]);
      return s;
    };
    const waveforms: string[] = [];
    for (let i = 0; i < m._webdsp_lfo_waveform_count(); i++) waveforms.push(cstr(m._webdsp_lfo_waveform_name(i)));
    const divisions: { name: string; beats: number }[] = [];
    for (let i = 0; i < m._webdsp_lfo_division_count(); i++) {
      divisions.push({ name: cstr(m._webdsp_lfo_division_name(i)), beats: m._webdsp_lfo_division_beats(i) });
    }
    return {
      maxLfos: m._webdsp_lfo_max(),
      waveforms,
      divisions,
      minRateHz: m._webdsp_lfo_min_rate(),
      maxRateHz: m._webdsp_lfo_max_rate(),
    };
  }

  private postEvent(event: WorkletEvent, transfer: Transferable[] = []) {
    this.port.postMessage(event, transfer);
  }

  private timeToFrame(seconds: number): number {
    return Math.round(seconds * sampleRate);
  }

  private handleCommand(cmd: HostCommand): void {
    try {
      this.handleCommandUnsafe(cmd);
    } catch (err) {
      // An uncaught exception anywhere AudioWorkletProcessor calls into user code disables
      // the node (process() silently stops being called from then on) — for a realtime
      // engine, one malformed command must not be able to kill the entire audio graph.
      this.postEvent({ type: "error", message: `command ${cmd.type} failed: ${String(err)}` });
    }
  }

  private handleCommandUnsafe(cmd: HostCommand): void {
    const m = this.module;
    if (!m) return; // dropped if it arrives before 'ready' — see workletBridge.ts, which queues

    switch (cmd.type) {
      case "load-sample": {
        const { sampleId, channels, sampleRate: sr, length, channelData } = cmd.sample;
        const channelPtrs = channelData.map((buf) => {
          const floatData = new Float32Array(buf);
          const ptr = m._webdsp_alloc_channel_buffer(length);
          m.HEAPF32.set(floatData, ptr >> 2);
          return ptr;
        });
        const table = m._webdsp_alloc_ptr_table(channels);
        m.HEAP32.set(channelPtrs, table >> 2);
        m._webdsp_commit_sample(sampleId, channels, length, sr, table);
        break;
      }
      case "unload-sample":
        m._webdsp_remove_sample(cmd.sampleId);
        break;
      case "trigger": {
        const p = cmd.params;
        const gain = p.gain ?? 1.0;
        const rate = (p.rate ?? 1.0) * (p.pitch ? Math.pow(2, p.pitch / 12) : 1.0);
        const start = p.start ?? 0;
        const end = p.end ?? -1;
        const loop = p.loop ? 1 : 0;
        const reverse = p.reverse ? 1 : 0;
        const bus = p.bus ?? 0;
        const duration = p.duration === undefined ? -1 : this.timeToFrame(p.duration);
        const pan = p.pan ?? 0;
        const region = p.region === undefined ? 0 : p.region + 1;
        if (p.time === undefined || this.timeToFrame(p.time) <= currentFrame) {
          m._webdsp_trigger(cmd.voice, p.sampleId, bus, gain, rate, start, end, loop, reverse, duration, pan, region);
        } else {
          m._webdsp_schedule_event(
            this.timeToFrame(p.time), cmd.voice, p.sampleId, bus, gain, rate, start, end, loop,
            reverse, duration, pan, region,
          );
        }
        break;
      }
      case "release":
        m._webdsp_release(cmd.voice);
        break;
      case "stop":
        m._webdsp_stop(cmd.voice);
        break;
      case "set-voice-param":
        m._webdsp_set_voice_param(cmd.voice, cmd.param, cmd.value);
        break;
      case "set-bus-param":
        m._webdsp_set_bus_param(cmd.bus, cmd.param, cmd.value);
        break;
      case "add-effect": {
        const ok = m._webdsp_fx_add(cmd.bus, cmd.effect, cmd.kind, cmd.index);
        if (!ok) {
          this.postEvent({ type: "error", message: `add-effect ${cmd.effect} on bus ${cmd.bus} rejected` });
        }
        break;
      }
      case "remove-effect":
        m._webdsp_fx_remove(cmd.bus, cmd.effect);
        break;
      case "move-effect":
        m._webdsp_fx_move(cmd.bus, cmd.effect, cmd.index);
        break;
      case "set-effect-enabled":
        m._webdsp_fx_set_enabled(cmd.bus, cmd.effect, cmd.enabled ? 1 : 0);
        break;
      case "set-effect-param":
        m._webdsp_fx_set_param(cmd.bus, cmd.effect, cmd.param, cmd.value);
        break;
      case "create-instrument":
        if (!m._webdsp_instrument_create(cmd.instrument, cmd.kind, cmd.bus)) {
          this.postEvent({ type: "error", message: `create-instrument ${cmd.instrument} rejected` });
        }
        break;
      case "remove-instrument":
        m._webdsp_instrument_remove(cmd.instrument);
        break;
      case "instrument-note-on": {
        const p = cmd.params;
        const velocity = p.velocity ?? 1.0;
        const pan = p.pan ?? 0;
        const pitch = p.pitch ?? 0;
        const duration = p.duration === undefined ? -1 : this.timeToFrame(p.duration);
        if (p.time === undefined || this.timeToFrame(p.time) <= currentFrame) {
          m._webdsp_instrument_note_on(cmd.instrument, velocity, pan, pitch, duration);
        } else {
          m._webdsp_schedule_instrument_note(
            this.timeToFrame(p.time), cmd.instrument, velocity, pan, pitch, duration,
          );
        }
        break;
      }
      case "instrument-note-off":
        m._webdsp_instrument_note_off(cmd.instrument);
        break;
      case "set-instrument-param":
        m._webdsp_instrument_set_param(cmd.instrument, cmd.param, cmd.value);
        break;
      case "set-effect-lfo":
        if (!m._webdsp_fx_set_lfo(
          cmd.bus, cmd.effect, cmd.slot, cmd.enabled ? 1 : 0, cmd.waveform, cmd.sync ? 1 : 0,
          cmd.rateHz, cmd.division, cmd.phase, cmd.amount, cmd.target,
        ) && cmd.enabled) {
          this.postEvent({ type: "error", message: `set-effect-lfo rejected (bus ${cmd.bus}, effect ${cmd.effect}, target ${cmd.target})` });
        }
        break;
      case "set-instrument-lfo":
        if (!m._webdsp_instrument_set_lfo(
          cmd.instrument, cmd.slot, cmd.enabled ? 1 : 0, cmd.waveform, cmd.sync ? 1 : 0, cmd.rateHz,
          cmd.division, cmd.phase, cmd.amount, cmd.target, cmd.retrigger ? 1 : 0,
        ) && cmd.enabled) {
          this.postEvent({ type: "error", message: `set-instrument-lfo rejected (instrument ${cmd.instrument}, target ${cmd.target})` });
        }
        break;
      case "set-transport":
        m._webdsp_set_transport(
          cmd.time === undefined ? 0 : this.timeToFrame(cmd.time),
          this.timeToFrame(cmd.anchorTime), cmd.bpm,
        );
        break;
      case "set-sample-regions":
        m._webdsp_clear_sample_regions(cmd.sample);
        for (const r of cmd.regions) m._webdsp_add_sample_region(cmd.sample, r.start | 0, r.end | 0);
        break;
      case "set-sample-param":
        m._webdsp_set_sample_param(cmd.sample, cmd.param, cmd.value);
        break;
      case "schedule":
        for (const e of cmd.events) {
          m._webdsp_schedule_event(
            this.timeToFrame(e.time), e.voice, e.sampleId, e.bus ?? 0, e.gain ?? 1.0,
            (e.rate ?? 1.0) * (e.pitch ? Math.pow(2, e.pitch / 12) : 1.0),
            e.start ?? 0, e.end ?? -1, e.loop ? 1 : 0, e.reverse ? 1 : 0,
            e.duration === undefined ? -1 : this.timeToFrame(e.duration), e.pan ?? 0,
            e.region === undefined ? 0 : e.region + 1,
          );
        }
        break;
      case "schedule-params":
        for (const e of cmd.events) {
          m._webdsp_schedule_param(
            this.timeToFrame(e.time), e.target, e.bus, e.id, e.param, e.value, e.from ?? 0,
            e.from === undefined ? 0 : 1, this.timeToFrame(e.ramp),
          );
        }
        break;
      case "cancel-scheduled":
        m._webdsp_cancel_scheduled(this.timeToFrame(cmd.fromTime ?? currentTime));
        break;
      case "start-capture":
        m._webdsp_start_capture(cmd.captureId, cmd.bus);
        break;
      case "stop-capture":
        m._webdsp_stop_capture(cmd.captureId);
        this.readAndPostCaptureComplete(m, cmd.captureId, cmd.resultSampleId);
        break;
      case "arm-capture": {
        const ok = m._webdsp_arm_capture(
          cmd.captureId, cmd.bus, this.timeToFrame(cmd.startTime), this.timeToFrame(cmd.stopTime),
        );
        if (ok) {
          this.armedCaptureResultIds.set(cmd.captureId, cmd.resultSampleId);
        } else {
          // Defensive-only path (native/src/capture.h's arm() refused the window) — a caller
          // is expected to have already checked RuntimeCapabilities.maxCaptureSeconds before
          // ever sending this command, see AudioRuntime.armCapture().
          this.postEvent({ type: "error", message: `arm-capture ${cmd.captureId} refused: window exceeds capture capacity` });
        }
        break;
      }
      case "configure":
        m._webdsp_configure_voices(cmd.maxVoices);
        break;
    }
  }

  // Shared by the manual stop-capture command and processUnsafe()'s poll for armed captures
  // that finished on their own — both end up needing the same "read PCM out of WASM memory,
  // post capture-complete, free the native buffer" sequence.
  private readAndPostCaptureComplete(m: EngineModule, captureId: number, resultSampleId: number): void {
    const length = m._webdsp_capture_length(captureId);
    const channels = m._webdsp_capture_channels(captureId);
    const channelData: ArrayBuffer[] = [];
    for (let c = 0; c < channels; c++) {
      const ptr = m._webdsp_capture_channel_ptr(captureId, c);
      const view = m.HEAPF32.subarray(ptr >> 2, (ptr >> 2) + length);
      channelData.push(Float32Array.from(view).buffer);
    }
    m._webdsp_discard_capture(captureId);
    this.postEvent(
      { type: "capture-complete", captureId, resultSampleId, channels, sampleRate, length, channelData },
      channelData,
    );
  }

  process(_inputs: Float32Array[][], outputs: Float32Array[][]): boolean {
    try {
      return this.processUnsafe(outputs);
    } catch (err) {
      this.postEvent({ type: "error", message: `render failed: ${String(err)}` });
      return true; // keep the node alive rather than let Chrome permanently disable it
    }
  }

  private processUnsafe(outputs: Float32Array[][]): boolean {
    const m = this.module;
    const output = outputs[0];
    if (!m || !output || !output[0]) return true;

    const numFrames = output[0].length;
    m._webdsp_process(currentFrame, numFrames);

    for (let c = 0; c < output.length; c++) {
      const ptr = m._webdsp_output_channel_ptr(c);
      output[c].set(m.HEAPF32.subarray(ptr >> 2, (ptr >> 2) + numFrames));
    }

    const endedCount = m._webdsp_ended_voice_count();
    for (let i = 0; i < endedCount; i++) {
      this.postEvent({ type: "voice-ended", voice: m._webdsp_ended_voice_id(i) });
    }

    // Armed captures (see "arm-capture" above) have no explicit stop command — the engine
    // itself decides when one reaches its armed stopFrame, so this is the other half of that
    // contract: notice it happened and finish the same way a manual stop-capture would.
    const finishedCaptureCount = m._webdsp_finished_capture_count();
    for (let i = 0; i < finishedCaptureCount; i++) {
      const captureId = m._webdsp_finished_capture_id(i);
      const resultSampleId = this.armedCaptureResultIds.get(captureId);
      this.armedCaptureResultIds.delete(captureId);
      if (resultSampleId === undefined) continue; // shouldn't happen; guard rather than crash the render thread
      this.readAndPostCaptureComplete(m, captureId, resultSampleId);
    }

    // CPU load and underrun counts are deliberately not part of this event — see
    // ARCHITECTURE.md, "Intentionally deferred": AudioWorkletGlobalScope has no
    // performance.now() (confirmed the hard way — it isn't part of the
    // WindowOrWorkerGlobalScope mixin worklets get), so there's no in-worklet wall-clock to
    // measure render time against, and the Web Audio API exposes no per-node underrun
    // counter at all. A fabricated always-zero value would be worse than not reporting it.
    this.blockCounter++;
    if (this.blockCounter % METERS_INTERVAL_BLOCKS === 0) {
      const count = m._webdsp_meter_count();
      const ptr = m._webdsp_read_meters() >> 2;
      const peaks = m.HEAPF32.subarray(ptr, ptr + count);
      let active = false;
      for (let i = 0; i < count; i++) {
        // Gain reduction (index 2) is <= 0, peaks are >= 0: either nonzero means activity.
        if (peaks[i] !== 0) { active = true; break; }
      }
      // Silence sends nothing, except one all-zero event so the UI sees the signal fall away.
      if (active || this.metersWereActive) this.postEvent({ type: "meters", peaks: Float32Array.from(peaks) });
      this.metersWereActive = active;
    }

    if (this.blockCounter % DIAGNOSTICS_INTERVAL_BLOCKS === 0) {
      this.postEvent({
        type: "diagnostics",
        activeVoices: m._webdsp_active_voice_count(),
        loadedSamples: m._webdsp_loaded_sample_count(),
        sampleMemoryBytes: m._webdsp_sample_memory_bytes(),
      });
    }

    return true;
  }
}

registerProcessor("webdsp-engine", EngineProcessor);
